head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF35005.xml"; //비상연락망 명부 목록

scwin.inputSeq;
scwin.gMsgStr;
scwin.gType;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market; // 세션의 시장구분
scwin.gSndloc = js_sndloc;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //송신처구분코드

scwin.fn_SetHeader = function() {
    // CUD용 Header
    dts_delList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=INT_ATSCONTACT_INOUT";
    dts_delList.Reset();
    dts_delList.insertRow();
};


//부서설정
scwin.fn_setCode = function() {
    if (scwin.gLdMktTp == "1" || scwin.gLdMktTp == "2") {
        //setObjectValue(rdo_MktTpCd, gLdMktTp);
        $c.stf.setObjectValue(rdo_MktTpCd, "9"); //시장구분 안함
        $c.stf.setObjectValue(rdo_SndLocTpCd, scwin.gSndloc);
    } else {
        $c.stf.showObj(panel_1, true);
        $c.stf.setObjectValue(rdo_MktTpCd, "9");
        $c.stf.setObjectValue(rdo_SndLocTpCd, "AA");
        $c.cm.setColumnProp(grd_Grid, "SNDLOC_TP_NM", "show", true);
    }

    //목록 조회
    scwin.fn_Search();
};
scwin.fn_Search = function() {
    var url = "/AtsContactInfo.do?method=atsEmContactNmList&inputMessageId=ATSCONTACTINFO_INOUT" + "&outputMessageId=ATSCONTACTINFO_INOUT" + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MktTpCd) + "&SNDLOC_TP_CD=" + $c.stf.getObjectValue(rdo_SndLocTpCd) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_list.DataID = encodeURI(url);
    dts_list.Reset();
    $c.cm.ShowWin(grd_Grid);
};


//삭제 처리
scwin.fn_approval = function(row, gType) {
    if (scwin.gType == "D") {
        scwin.gMsgStr = "삭제";
    }
    var rtn = window.confirm('[' + scwin.gMsgStr + ']하시겠습니까?');
    if (rtn == 1) {
        dts_delList.setCellData(1, "NMLIST_SEQ", dts_list.getCellData(row, "NMLIST_SEQ"));
        dts_delList.setCellData(1, "CONTN_ID", scwin.gType);
        dts_delList.setCellData(1, "LST_ADJPRN_ID", scwin.gEmpNo);
        trs_Save.Action = "/AtsContactInfo.do?method=registerAtsEmContactNm&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_delList)";
        trs_Save.Post();
    }
};
scwin.fn_setApplNo = function(obj) {
    scwin.inputSeq = dts_list.getCellData(eval(obj), "NMLIST_SEQ");
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "비상연락망 " + scwin.gMsgStr));
    scwin.fn_Search();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "비상연락망 " + scwin.gMsgStr));
};
scwin.dts_list_OnLoadCompleted = function(rowcount) {
    if (dts_list.errorMsg) {
        $c.win.alert("조회시 오류가 발생하였습니다. 시스템관리자에게 문의하세요");
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_list_OnLoadError = function() {
    $c.cm.CloseWin('', grd_Grid);
    $c.win.alert("조회시 오류가 발생하였습니다. 시스템관리자에게 문의하세요");
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "비상연락망", "", "8");
};
scwin.grd_Grid_OnClick = async function(row, colid) {
    if (row >= 1) {
        if (colid == "UPDATE_YN") {
            scwin.gType = 'U'; //수정
            scwin.fn_setApplNo(row);
            await $c.frame.CreateDialogFrame("gform", "/dscltrend/ULDSTF35005_POP.gfm", "비상연락망 수정", 200, 100, 635, 270, "window");
        } else if (colid == "DEL_YN") {
            scwin.gType = 'D'; //삭제
            scwin.fn_approval(row, scwin.gType);
        }
    }
};
scwin.btn_new_onclick = async function() {
    scwin.gType = "N"; //신규
    await $c.frame.CreateDialogFrame("gform", "/dscltrend/ULDSTF35005_POP.gfm", "비상연락망 신규등록", 200, 100, 650, 270, "window");
};
scwin.gform_onload = function() {
    //PanelToGroupBox(panel_1);    
    $c.stf.showObj(panel_1, false);
    $c.stf.showObj(tbox_nmlist_seq, false);
    $c.cm.setColumnProp(grd_Grid, "SNDLOC_TP_NM", "show", false);
    scwin.fn_setCode();
    scwin.fn_SetHeader();
};
